import React, {
  createContext,
  useContext,
  useEffect,
  useState,
} from "react";

import api from "../services/api.js"

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);

  const [loading, setLoading] = useState(true);

  const loadUser = async () => {
    try {
      const data = await api("/auth/me");

      setUser(data.user);
    } catch (error) {
      setUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadUser();
  }, []);

  const login = async (
    email,
    password
  ) => {
    const data = await api(
      "/auth/login",
      {
        method: "POST",
        body: {
          email,
          password,
        },
      }
    );

    setUser(data.user);

    return data;
  };

  const logout = async() => {
    await api(
      "/auth/logout",
      {
        method: "POST",
      }
    );
    setUser(null);
  };



  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        login,
        logout,
        updateUser,
        isAuthenticated: Boolean(token),
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
